package org.pqcfuzz.target.jdk;

import org.pqcfuzz.util.DeterministicSecureRandom;

import java.security.GeneralSecurityException;
import java.security.KeyPair;
import java.security.KeyPairGenerator;
import java.security.SecureRandom;
import java.security.spec.NamedParameterSpec;

import javax.crypto.KEM;

/**
 * ML-KEM-768 key material for the JDK decapsulation target: a key pair generated by the JDK itself
 * from the campaign seed, and seeded encapsulations for the corpus.
 *
 * <p>Unlike the ML-DSA material this is <em>not</em> the BouncyCastle arm's key pair: JDK 24 cannot
 * import BouncyCastle's PKCS#8 encoding of an ML-KEM private key (JDK 27 can), so the decapsulation
 * target derives its own pair from the seed instead. The JDK's generator draws its seed bytes from
 * the supplied {@link SecureRandom}, so the pair is a function of the campaign seed all the same.
 */
final class JdkMlKemKeys {

    final KeyPair keyPair;
    final KEM kem;
    final KEM.Decapsulator decapsulator;
    private final SecureRandom encapsulationRandom;

    JdkMlKemKeys(long seed) {
        try {
            KeyPairGenerator generator = KeyPairGenerator.getInstance("ML-KEM-768");
            generator.initialize(new NamedParameterSpec("ML-KEM-768"), new DeterministicSecureRandom(seed));
            this.keyPair = generator.generateKeyPair();
            this.kem = JdkPqc.kem("ML-KEM-768");
            this.decapsulator = kem.newDecapsulator(keyPair.getPrivate());
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("JDK ML-KEM-768 key generation failed", e);
        }
        // A distinct stream for encapsulations, so seed ciphertexts vary but stay reproducible.
        this.encapsulationRandom = new DeterministicSecureRandom(seed ^ 0x5555_AAAAL);
    }

    byte[] encapsulate() {
        try {
            return kem.newEncapsulator(keyPair.getPublic(), encapsulationRandom).encapsulate().encapsulation();
        } catch (GeneralSecurityException e) {
            throw new IllegalStateException("JDK ML-KEM-768 encapsulation failed while building the corpus", e);
        }
    }
}
